#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Class definition for one of Velocity's REST api services.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"


import method as velocity_method


class CService(object):
    method_lookup = {
        "get": "panel panel-info",
        "post": "panel panel-success",
        "put": "panel panel-warning",
        "delete": "panel panel-danger"
    }

    def __init__(self, section):
        self.section = section
        self.methods = {}
        for key in self.method_lookup:
            self.methods[key] = self.section.find_all(
                "section", {"class": self.method_lookup[key]}
            )

    def __str__(self):
        return self.section.text

    def parse(self):
        for key in self.methods:
            for method in self.methods[key]:
                function = velocity_method.CMethod(method, key)
                function.parse()
                print(function)
